40	/* ==========================================================================
41	 * Hosting console — the plan-as-workspace shell.
42	 *
43	 * Two views, both URL-addressable so links survive a refresh:
44	 *   • PLAN CONSOLE (default)  — header + resource stat-cards (the primary nav) +
45	 *     the website grid (the hub) + Activity / Plan / Usage + a slim connection rail.
46	 *     Plan-scoped resource SECTIONS (Databases, Email, Backups, Domains, Files,
47	 *     Cron, Logs, Settings) reuse the existing panels verbatim, reached from the
48	 *     stat-cards and a secondary in-plan nav.  URL: `?tab=<section>`.
49	 *   • WEBSITE DETAIL          — scoped to ONE website (primary / subdomain / addon)
50	 *     with its own sub-nav (Overview, App, Files, Domains & SSL, Email, Databases,
51	 *     Logs, Settings), reusing the per-site install / file-manager / set-primary
52	 *     capabilities.  URL: `?site=<id|primary>&stab=<subtab>`.
53	 *
54	 * Every read/mutation is a real ownership-guarded server action — no mock data.
55	 * ======================================================================== */
56	
57	const SECTIONS: [key: string, label: string][] = [
58	  ["databases", "Databases"],
59	  ["email", "Email"],
60	  ["backups", "Backups"],
61	  ["domains", "Domains & SSL"],
62	  ["files", "File Manager"],
63	  ["cron", "Cron"],
64	  ["logs", "Logs"],
65	  ["settings", "Settings"],
66	];
67	const SECTION_KEYS = SECTIONS.map(([k]) => k);
68	
69	const SITE_TABS: [key: string, label: string][] = [
70	  ["overview", "Overview"],
71	  ["app", "App"],
72	  ["files", "Files"],
73	  ["domains", "Domains & SSL"],
74	  ["email", "Email"],
75	  ["databases", "Databases"],
76	  ["logs", "Logs"],
77	  ["settings", "Settings"],
78	];
79	const SITE_TAB_KEYS = SITE_TABS.map(([k]) => k);
80	
81	type Counts = {
82	  websites: number;
83	  dbs: number;
84	  backups: number;
85	  emailUsed: number;
86	  emailCap: number | null;
87	  subs: number;
88	  addons: number;
89	};
90	
91	export function HostingConsole({
92	  account,
93	  initialTab,
94	  initialPath,
95	  initialSite,
96	  initialSiteTab,
97	}: {
98	  account: HostingAccountView;
99	  initialTab?: string;
100	  initialPath?: string;
101	  initialSite?: string;
102	  initialSiteTab?: string;
103	}) {
104	  const active = account.status === "ACTIVE";
105	
106	  // ---- view state --------------------------------------------------------
107	  const [siteParam, setSiteParam] = useState<string | undefined>(initialSite);
108	  const [siteTab, setSiteTab] = useState<string>(
109	    initialSiteTab && SITE_TAB_KEYS.includes(initialSiteTab) ? initialSiteTab : "overview",
110	  );
111	  // "console" = the hub; otherwise one of SECTION_KEYS.
112	  const [section, setSection] = useState<string>(
113	    initialTab && SECTION_KEYS.includes(initialTab) ? initialTab : "console",
114	  );
115	
116	  // Live website list — powers the grid, the switcher and the website-count card.
117	  const [sites, setSites] = useState<HostingWebsiteView[] | null>(null);
118	  const refreshSites = useCallback(() => {
119	    if (!active) { setSites([]); return; }
120	    listWebsites(account.id).then(setSites).catch(() => setSites([]));
121	  }, [account.id, active]);
122	  useEffect(() => { refreshSites(); }, [refreshSites]);
123	
124	  // ---- URL sync ----------------------------------------------------------
125	  function pushUrl(params: Record<string, string | undefined>) {
126	    const qs = new URLSearchParams();
127	    for (const [k, v] of Object.entries(params)) if (v) qs.set(k, v);
128	    const s = qs.toString();
129	    window.history.replaceState(null, "", s ? `?${s}` : window.location.pathname);
130	  }
131	  const goHub = useCallback(() => {
132	    setSiteParam(undefined); setSection("console"); pushUrl({}); window.scrollTo(0, 0);
133	  }, []);
134	  const goSection = useCallback((sec: string) => {
135	    setSiteParam(undefined); setSection(sec); pushUrl({ tab: sec }); window.scrollTo(0, 0);
136	  }, []);
137	  const openSite = useCallback((param: string) => {
138	    setSiteParam(param); setSiteTab("overview"); pushUrl({ site: param, stab: "overview" }); window.scrollTo(0, 0);
139	  }, []);
140	  const goSiteTab = useCallback((t: string) => {
141	    setSiteTab(t); setSiteParam((p) => { pushUrl({ site: p, stab: t }); return p; });
142	  }, []);
143	
144	  return (
145	    <div>
146	      {siteParam ? (
147	        <WebsiteDetail
148	          account={account}
149	          sites={sites}
150	          siteParam={siteParam}
151	          siteTab={siteTab}
152	          onHub={goHub}
153	          onSiteTab={goSiteTab}
154	          onSection={goSection}
155	          onSitesChanged={refreshSites}
156	        />
157	      ) : section === "console" ? (
158	        <PlanConsole
159	          account={account}
160	          sites={sites}
161	          onOpenSite={openSite}
162	          onSection={goSection}
163	          onSitesChanged={refreshSites}
164	        />
165	      ) : (
166	        <PlanSection account={account} section={section} initialPath={initialPath} onHub={goHub} onSection={goSection} />
167	      )}
168	    </div>
169	  );
170	}
