177	  const [busy, setBusy] = useState(false);
178	  const [err, setErr] = useState("");
179	
180	  async function save() {
181	    setBusy(true); setErr("");
182	    const r = await renameHostingAccount(account.id, value);
183	    setBusy(false);
184	    if (r.error) { setErr(r.error); return; }
185	    setEditing(false);
186	    onRenamed?.();
187	    window.location.reload();
188	  }
189	
190	  return (
191	    <div className="mb-6">
192	      <div className="flex flex-wrap items-center gap-3">
193	        {editing ? (
194	          <div className="flex flex-wrap items-center gap-2">
195	            <input
196	              className="input max-w-[280px] text-lg font-semibold"
197	              value={value}
198	              maxLength={60}
199	              autoFocus
200	              disabled={busy}
201	              placeholder={`My ${account.planName} workspace`}
202	              onChange={(e) => setValue(e.target.value)}
203	              onKeyDown={(e) => { if (e.key === "Enter") save(); if (e.key === "Escape") setEditing(false); }}
204	            />
205	            <button className="btn-primary px-3 py-1.5 text-sm" disabled={busy} onClick={save}>{busy ? "Saving…" : "Save"}</button>
206	            <button className="btn-secondary px-3 py-1.5 text-sm" disabled={busy} onClick={() => { setEditing(false); setValue(account.name ?? ""); }}>Cancel</button>
207	          </div>
208	        ) : (
209	          <>
210	            <h1 className="page-title">{account.displayName}</h1>
211	            <button
212	              type="button"
213	              title="Rename this plan"
214	              onClick={() => setEditing(true)}
215	              className="rounded-md border border-white/[0.08] bg-white/[0.03] p-1.5 text-slate-400 hover:text-white"
216	            >
217	              <svg viewBox="0 0 20 20" fill="none" className="h-3.5 w-3.5"><path d="M13.5 3.5l3 3L7 16l-3.5.5L4 13l9.5-9.5z" stroke="currentColor" strokeWidth="1.4" strokeLinejoin="round" /></svg>
218	            </button>
