229	          rel="noreferrer"
230	          className="rounded-md border border-white/[0.08] bg-white/[0.03] px-2 py-0.5 font-mono text-xs text-slate-300 hover:text-white"
231	        >
232	          {account.primaryDomain}
233	        </a>
234	        {account.sslActive && <Badge tone="green">HTTPS</Badge>}
235	        <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">← All hosting</a>
236	      </div>
