241	/* =========================================================== plan console === */
242	
243	function PlanConsole({
244	  account,
245	  sites,
246	  onOpenSite,
247	  onSection,
248	  onSitesChanged,
249	}: {
250	  account: HostingAccountView;
251	  sites: HostingWebsiteView[] | null;
252	  onOpenSite: (param: string) => void;
253	  onSection: (sec: string) => void;
254	  onSitesChanged: () => void;
255	}) {
256	  const active = account.status === "ACTIVE";
257	  const gridRef = useRef<HTMLDivElement>(null);
258	  const [counts, setCounts] = useState<Counts | null>(null);
259	
260	  // Live resource counts for the stat-cards — each from its real, ownership-guarded
261	  // read. Failures degrade to 0 rather than blocking the console.
262	  useEffect(() => {
263	    if (!active) return;
264	    let live = true;
265	    Promise.all([
266	      listHostingDatabases(account.id).catch(() => []),
267	      listHostingBackups(account.id).catch(() => []),
268	      listHostingSubdomains(account.id).catch(() => []),
269	      listHostingAddonDomains(account.id).catch(() => []),
270	      getHostingEmailStatus(account.id).catch(() => null),
271	    ]).then(([dbs, backups, subs, addons, email]) => {
272	      if (!live) return;
273	      setCounts({
274	        websites: 0, // filled from `sites` below
275	        dbs: dbs.length,
276	        backups: backups.length,
277	        emailUsed: email?.bundled?.mailboxes.length ?? 0,
278	        emailCap: email?.includedMailboxes ?? null,
279	        subs: subs.filter((s) => s.status !== "DELETING").length,
280	        addons: addons.filter((d) => d.status !== "DELETING").length,
281	      });
282	    });
283	    return () => { live = false; };
284	  }, [account.id, active]);
285	
286	  const siteCount = sites?.length ?? 0;
287	  const siteCap = 1 + account.maxSites; // primary + extra sites
288	  const diskGB = Math.round(account.diskQuotaMB / 1024);
289	  const usedGB = account.diskUsedMB != null ? account.diskUsedMB / 1024 : null;
290	
291	  function scrollToGrid() {
292	    gridRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
293	  }
294	
295	  return (
296	    <div>
297	      <div className="flex flex-wrap items-start gap-3">
