787	            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
788	          </div>
789	        ))}
790	      </div>
791	      <div className="mt-1.5 flex items-start justify-between text-[11px]">
792	        {steps.map((s) => (
793	          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
794	            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
795	          </div>
