299	          maxDatabases: limits.maxDatabases,
300	          // The term this account was SOLD on, and the annual rate frozen at sale, so
301	          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
302	          termMonths: term,
303	          annualDiscountPct: annualPct,
304	          expiresAt: addMonths(new Date(), term),
305	        } as Prisma.HostingAccountUncheckedCreateInput,
306	      });
307	      accountId = acct.id;
308	      // Atomic hostname claim in the SAME tx as the account row. A colliding
309	      // primaryDomain (another order, or someone's subdomain/addon of the same
310	      // name racing us past the advisory isHostnameClaimed check) fails here on
311	      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
312	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
313	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
314	    });
315	  } catch (e) {
316	    if (isUniqueViolation(e)) {
317	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
318	    }
319	    // The generic message below is intentionally opaque to the customer, but the
320	    // REAL error must be diagnosable server-side (e.g. prod schema drift: a
321	    // HostingAccount.termMonths/annualDiscountPct column or the HostingHostnameClaim
322	    // table missing because a `prisma db push` didn't apply → the INSERT throws
323	    // here). Log it before swallowing. No money-logic change — the tx already rolled
324	    // back, so the wallet was NOT charged.
325	    console.error("[hosting.order] failed", {
326	      userId: user.id,
327	      planId,
328	      domain: name,
329	      code: (e as { code?: string })?.code,
330	      err: e instanceof Error ? e.message : e,
331	    });
332	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
333	  }
334	
335	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
336	  revalidatePath("/dashboard/hosting");
337	  return { ok: true, accountId };
338	}
