340	// ---------- Checkout wizard (payment-method-captured order) ------------------
341	//
342	// THE MONEY FIX. `orderHostingAccount` above debits the WALLET only. First-month-
343	// free (hosting-only) makes a monthly plan $0 for month 1, so the wallet path used
344	// to provision with NOTHING on file — and month-2's renewal had nothing to charge.
345	// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
346	// REFUSES to provision unless the account has a way to bill the renewal (a saved
347	// card OR a wallet balance that already covers one renewal), it is idempotent
348	// against double-submit, and it then delegates the ACTUAL charge to the audited
349	// `orderHostingAccount` above — one debit path, never a second one.
350	//
351	// displayed === charged === renewed: this action computes NO price of its own for
352	// the debit. The wallet debit + the first-month-free reserve→confirm→release
353	// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
354	// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
355	// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).
356	
357	export type HostingOrderInput = {
358	  planId: string;
359	  /** Empty/omitted => a free `<label|username>.<base>` subdomain (see subdomainLabel). */
360	  domain?: string;
361	  /** Customer-chosen free-subdomain label (used only when `domain` is empty). */
362	  subdomainLabel?: string;
363	  /** Optional extra storage (GB) bought at deploy, on top of the plan allowance. */
364	  extraDiskGB?: number;
365	  termMonths?: number;
366	  /** Optional catalog app to auto-install after the account provisions. */
367	  appSlug?: string;
368	  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
369	  idempotencyKey: string;
370	};
371	
372	export type HostingOrderResult =
373	  | { ok: true; accountId: string }
374	  | { error: string }
375	  /** No renewal-capable payment method yet — the wizard must capture a card first. */
376	  | { needCard: true; renewalCents: number };
