378	/**
379	 * The full-price single renewal of a plan/term — the gate threshold, identical to
380	 * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
381	 */
382	async function hostingRenewalCents(plan: { priceCents: number }, term: number, extraGB = 0): Promise<number> {
383	  const annualPct = await annualDiscountPct();
384	  const perGbCents = await extraDiskPerGbCents();
385	  return termPriceCents(plan.priceCents, term, annualPct) + extraDiskCentsAt(extraGB, perGbCents) * term;
386	}
