388	/** Place a hosting order from the checkout wizard. See the block comment above. */
389	export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
390	  const user = await requireUser();
391	  await assertNotImpersonating();
392	  const unverified = await emailVerificationError(user);
393	  if (unverified) return { error: unverified };
394	
395	  const key = String(input.idempotencyKey ?? "").trim();
396	  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };
397	
398	  const term = normalizeProductTerm(input.termMonths);
399	  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
400	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
401	
402	  // RENEWAL-METHOD GATE — the core fix. Never provision a paid product with no way
403	  // to bill the renewal. A saved card (charged off-session by the renewal sweep) OR
404	  // a wallet already holding one renewal's worth qualifies; otherwise the wizard
405	  // sends the customer to Stripe to capture a card (which also handles the $0-today
406	  // case, where no card would otherwise be collected).
407	  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
408	  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
409	  if (!hasChargeableCard(user) && user.balanceCents < renewalCents) {
410	    return { needCard: true, renewalCents };
411	  }
412	
413	  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
414	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
415	  // token table. A rapid resubmit or a network retry with the same key can't create
416	  // a second account or take a second debit.
417	  const sessionKey = `hostorder:${key}`;
418	  try {
419	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
420	  } catch (e) {
421	    if (isUniqueViolation(e)) {
422	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
423	      // A completed prior attempt: replay its result (no second charge).
424	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
425	      // A failed prior attempt: clear it so an explicit retry can proceed.
426	      if (prior?.status === "FAILED") {
427	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
428	      } else {
429	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
430	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
431	      }
432	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
433	      try {
434	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
435	      } catch {
436	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
437	      }
438	    } else {
439	      throw e;
440	    }
441	  }
442	
443	  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
444	  // the free temporary subdomain. All money movement, the first-month-free atomic
445	  // claim and the hostname claim happen inside orderHostingAccount's transaction.
446	  const res = await orderHostingAccount(input.planId, input.domain ?? "", term, input.subdomainLabel, extraGB);
447	  if (res.error || !res.accountId) {
448	    await db.fulfilledSession
449	      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: (res.error ?? "order failed").slice(0, 500) } })
450	      .catch(() => {});
451	    return { error: res.error ?? "Couldn’t place the order. Your wallet was not charged — try again." };
452	  }
453	  await db.fulfilledSession
454	    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
455	    .catch(() => {});
456	
457	  // Server-side Meta CAPI `Subscribe` — the free-month hosting signup is a browser-
458	  // ONLY conversion otherwise (HostingDeployWizard fires nxTrack('hosting') client-
459	  // side), so an ad blocker / privacy browser silently drops it and the campaign
460	  // never learns the signup happened. Firing it here too — with the SAME event_id
461	  // the browser pixel uses (idempotencyKey) — means Meta dedupes the two into ONE
462	  // conversion when the pixel DOES load, and still counts it when the pixel is
463	  // blocked. Value = the go-forward renewal (what optimisation should chase), NOT $0.
464	  // Best-effort: sendMetaConversion never throws, and this runs after the order is
465	  // already committed, so tracking can never affect the charge.
466	  try {
467	    const [h, ck] = await Promise.all([headers(), cookies()]);
468	    await sendMetaConversion({
469	      eventName: "Subscribe",
470	      eventId: key,
471	      email: user.email,
472	      externalId: user.id,
473	      value: renewalCents / 100,
474	      currency: "USD",
475	      clientIp: clientIp(h),
476	      userAgent: h.get("user-agent") ?? undefined,
477	      // The Meta click/browser cookies are the strongest match signals for an
478	      // ad-driven signup (an ad click sets _fbc). Passing them lifts Event Match
479	      // Quality well above the email/IP-only baseline. Absent for organic visits.
480	      fbc: ck.get("_fbc")?.value || undefined,
481	      fbp: ck.get("_fbp")?.value || undefined,
482	      sourceUrl: process.env.APP_URL ? `${process.env.APP_URL}/dashboard/deploy` : undefined,
483	    });
484	  } catch {
485	    /* tracking is best-effort — the order is already placed and charged */
486	  }
487	
488	  // Optional one-click app install: queue it now so the worker installs it the
489	  // moment the account finishes provisioning. Best-effort — a bad slug never voids
490	  // the (already-charged) order; the customer can install from the panel later.
491	  const slug = String(input.appSlug ?? "").trim();
492	  if (slug) {
493	    try {
494	      await queueHostingAppInstall(res.accountId, slug, plan.maxDatabases, user.email);
495	    } catch {
496	      /* non-fatal: the account is created and charged; the app can be installed later */
497	    }
498	  }
499	
500	  revalidatePath("/dashboard/hosting");
501	  return { ok: true, accountId: res.accountId };
502	}
