504	/**
505	 * Live availability check for a customer-chosen free subdomain (`<label>.<base>`).
506	 * Advisory UX for the deploy wizard — the authoritative de-dup is the atomic
507	 * UNIQUE(hostname) claim inside orderHostingAccount's charge tx, so a check that
508	 * says "available" can still lose a race and fail the order cleanly (no charge).
509	 */
510	export async function checkHostingSubdomain(
511	  labelRaw: string,
512	): Promise<{ available: boolean; fqdn: string; reason?: string }> {
513	  await requireUser();
514	  const label = String(labelRaw ?? "").trim().toLowerCase();
515	  const fqdn = freeSubdomainFor(label);
516	  if (!label) return { available: false, fqdn, reason: "Enter a subdomain." };
517	  if (!isValidSubdomainLabel(label)) {
518	    return { available: false, fqdn, reason: "Use 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
519	  }
520	  if (!isValidHostingDomain(fqdn)) {
521	    return { available: false, fqdn, reason: "That subdomain isn’t a valid hostname." };
522	  }
523	  if (await isHostnameClaimed(fqdn)) {
524	    return { available: false, fqdn, reason: "Already taken — try another." };
525	  }
526	  return { available: true, fqdn };
527	}
