529	/**
530	 * Queue an APP_INSTALL for a freshly-ordered (PENDING) account. Mirrors installApp
531	 * but without the ACTIVE gate — the task waits in the queue and the worker runs it
532	 * after provisioning. Generates DB credentials up front for apps that need one.
533	 */
534	async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
535	  // WordPress is NOT an APP_RECIPES download — it installs via its own fully-
536	  // automated WORDPRESS_INSTALL task (WP-CLI). Route the wizard's one-click
537	  // WordPress here so it queues the right task with the same credential payload
538	  // installWordPress builds (mirrors that path). Any other slug must be a known
539	  // recipe app; an unknown slug is dropped (best-effort — never voids the order).
540	  if (slug === "wordpress") {
541	    if (maxDatabases < 1) return; // WordPress needs a database — no budget, skip rather than fail
542	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
543	    if (!acct) return;
544	    const dbName = `${acct.username}_wp`.slice(0, 64);
545	    const dbUser = dbName.slice(0, 32);
546	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
547	    const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
548	    await db.hostingTask.create({
549	      data: {
550	        accountId,
551	        kind: "WORDPRESS_INSTALL",
552	        payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: email }),
553	      },
554	    });
555	    return;
556	  }
557	  const app = hostingAppCatalog().find((x) => x.slug === slug);
558	  if (!app) return;
559	  let payload: Record<string, unknown> = { slug };
560	  if (app.needsDb) {
561	    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
562	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
563	    if (!acct) return;
564	    const dbName = `${acct.username}_${slug}`.slice(0, 64);
565	    const dbUser = dbName.slice(0, 32);
566	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
567	    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
568	  }
569	  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
570	}
