686	  // (matches orderHostingAccount/createHostingDatabase — audit LOW-1).
687	  await assertNotImpersonating();
688	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, sftpPasswordEnc: true } });
689	  if (!a) return { error: "Not found." };
690	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
691	  const pw = a.sftpPasswordEnc ? decryptSecret(a.sftpPasswordEnc) : null;
692	  if (!pw) return { error: "No password on record yet — the account is still being set up." };
693	  return { password: pw };
