771	/** Create a scoped database for an account (within the plan's maxDatabases). */
772	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
773	  const user = await requireUser();
774	  await assertNotImpersonating();
775	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
776	  if (!a) return { error: "Account not found." };
777	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
778	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
779	  // A short, safe suffix keyed off the account username: <user>_<slug>.
780	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
781	  const name = `${a.username}_${slug}`.slice(0, 64);
782	  const dbUser = name.slice(0, 32);
783	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
784	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
785	  // Count + create in ONE serializable transaction, so concurrent creates can't
786	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
787	  try {
788	    await db.$transaction(async (tx) => {
789	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
790	      if (n >= a.maxDatabases) throw new Error("CAP");
791	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
792	    }, { isolationLevel: "Serializable" });
793	  } catch (e) {
794	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
795	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
796	    return { error: "A database with that name already exists, or the request raced — try again." };
797	  }
798	  revalidatePath("/dashboard/hosting");
799	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
800	  return { ok: true, password };
801	}
