930	 * apps), read from their install-task results for the Overview's App Credentials panel.
931	 * Ownership-checked and blocked under impersonation, exactly like the SFTP/DB reveals —
932	 * these are live secrets. Newest install first; a result that isn't a login is skipped.
933	 */
934	export async function getHostingAppCredentials(
935	  accountId: string,
936	): Promise<{ site: string; app: string; url: string; adminUser: string; adminPassword: string; at: string }[]> {
937	  const user = await requireUser();
938	  await assertNotImpersonating();
939	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, primaryDomain: true } });
940	  if (!a) return [];
941	  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
942	
943	  // Resolve an install's target (primary / subdomain:<id> / addon:<id>) → the
944	  // website hostname it belongs to, so each credential is labelled with its site and
945	  // we can keep exactly ONE (the newest) per website — two WordPress installs on the
946	  // same site no longer show as two identical rows.
947	  const [subs, addons, rows] = await Promise.all([
948	    db.hostingSubdomain.findMany({ where: { accountId }, select: { id: true, fqdn: true } }),
949	    db.hostingAddonDomain.findMany({ where: { accountId }, select: { id: true, domain: true } }),
950	    db.hostingTask.findMany({
951	      where: { accountId, status: "DONE", kind: { in: ["WORDPRESS_INSTALL", "APP_INSTALL"] }, result: { not: null } },
952	      orderBy: { createdAt: "desc" },
953	      take: 50,
954	    }),
955	  ]);
956	  const subHost = new Map(subs.map((s) => [s.id, s.fqdn]));
957	  const addonHost = new Map(addons.map((d) => [d.id, d.domain]));
958	
959	  const out: { site: string; app: string; url: string; adminUser: string; adminPassword: string; at: string }[] = [];
960	  const seen = new Set<string>(); // one credential per resolved site key (newest wins — rows are desc)
961	  for (const t of rows) {
962	    let p: { adminUser?: string; adminPassword?: string; url?: string; app?: string; name?: string } | null = null;
963	    let target: { kind?: string; id?: string } = {};
964	    try { p = JSON.parse(t.result || ""); } catch { p = null; }
965	    try { target = (JSON.parse(t.payload || "{}").target ?? {}) as { kind?: string; id?: string }; } catch { /* */ }
966	    if (!p || !p.adminUser || !p.adminPassword) continue;
967	
968	    const siteKey = target.kind === "subdomain" && target.id ? `subdomain:${target.id}`
969	      : target.kind === "addon" && target.id ? `addon:${target.id}`
970	      : "primary";
971	    if (seen.has(siteKey)) continue;
972	    seen.add(siteKey);
973	
974	    const site = target.kind === "subdomain" && target.id ? (subHost.get(target.id) ?? a.primaryDomain)
975	      : target.kind === "addon" && target.id ? (addonHost.get(target.id) ?? a.primaryDomain)
976	      : a.primaryDomain;
977	
978	    out.push({
979	      site,
980	      app: p.app || p.name || (t.kind === "WORDPRESS_INSTALL" ? "WordPress" : "App"),
981	      url: p.url || "",
982	      adminUser: p.adminUser,
983	      adminPassword: p.adminPassword,
984	      at: t.createdAt.toISOString(),
985	    });
986	  }
987	  return out;
988	}
