1037	/**
1038	 * Validate an install target against an account (cross-tenant guard at the action
1039	 * layer, mirrored again in the worker). For a subdomain/addon the row must exist,
1040	 * belong to THIS account, and be ACTIVE. Returns the JSON `target` to embed in the
1041	 * task payload (undefined for primary → the worker's back-compat default) plus a
1042	 * short, DB-safe suffix that keeps each site's generated database name distinct.
1043	 */
1044	async function validateSiteTarget(
1045	  accountId: string,
1046	  target: SiteTarget | undefined,
1047	): Promise<{ error?: string; payloadTarget?: { kind: string; id: string }; dbSuffix: string }> {
1048	  const kind = target?.kind ?? "primary";
1049	  if (kind === "primary") return { dbSuffix: "" };
1050	  const id = "id" in (target ?? {}) ? String((target as { id: string }).id) : "";
1051	  if (!id) return { error: "Choose a website to install onto.", dbSuffix: "" };
1052	  if (kind === "subdomain") {
1053	    const sub = await db.hostingSubdomain.findFirst({ where: { id, accountId }, select: { status: true } });
1054	    if (!sub) return { error: "That subdomain isn’t part of this account.", dbSuffix: "" };
1055	    if (sub.status !== "ACTIVE") return { error: "That subdomain is still being set up.", dbSuffix: "" };
1056	    return { payloadTarget: { kind: "subdomain", id }, dbSuffix: randomBytes(3).toString("hex") };
1057	  }
1058	  if (kind === "addon") {
1059	    const addon = await db.hostingAddonDomain.findFirst({ where: { id, accountId }, select: { status: true } });
1060	    if (!addon) return { error: "That domain isn’t part of this account.", dbSuffix: "" };
1061	    if (addon.status !== "ACTIVE") return { error: "That domain is still being set up.", dbSuffix: "" };
1062	    return { payloadTarget: { kind: "addon", id }, dbSuffix: randomBytes(3).toString("hex") };
1063	  }
1064	  return { error: "Unknown install target.", dbSuffix: "" };
1065	}
