1067	export async function installWordPress(accountId: string, target?: SiteTarget): Promise<HostingResult> {
1068	  const ctx = await ownedActiveAccount(accountId);
1069	  if ("error" in ctx) return { error: ctx.error };
1070	  const { user, a } = ctx;
1071	  if (a._count.databases >= a.maxDatabases) return { error: `WordPress needs a database, but your plan's ${a.maxDatabases} are used. Delete one first.` };
1072	  const tgt = await validateSiteTarget(accountId, target);
1073	  if (tgt.error) return { error: tgt.error };
1074	  // Generate all creds up front; the worker applies them, then the admin login is
1075	  // returned ONCE via the task result. A per-site suffix keeps each site's DB name
1076	  // unique (primary keeps the legacy `<user>_wp` name for back-compat).
1077	  const dbName = `${a.username}_wp${tgt.dbSuffix}`.slice(0, 64);
1078	  const dbUser = dbName.slice(0, 32);
1079	  const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
1080	  const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
1081	  await db.hostingTask.create({
1082	    data: {
1083	      accountId,
1084	      kind: "WORDPRESS_INSTALL",
1085	      payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: user.email, ...(tgt.payloadTarget ? { target: tgt.payloadTarget } : {}) }),
1086	    },
1087	  });
1088	  revalidatePath("/dashboard/hosting");
1089	  return { ok: true };
1090	}
