1547	export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
1548	  const ctx = await ownedSiteAccount(accountId);
1549	  if ("error" in ctx) return { error: ctx.error };
1550	  const { a } = ctx;
1551	  const clean = String(label ?? "").trim().toLowerCase();
1552	  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
1553	  const fqdn = `${clean}.${a.primaryDomain}`;
1554	  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
1555	  // Reject if another tenant already claimed this exact hostname as an addon domain
1556	  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
1557	  // path (audit HIGH-1, reverse direction).
1558	  if (await isHostnameClaimed(fqdn)) {
1559	    return { error: "That hostname is already in use on Nxeon." };
1560	  }
1561	  const { docroot } = subdomainPaths(a.username, clean);
1562	  try {
1563	    await db.$transaction(async (tx) => {
1564	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1565	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1566	      if (subs + addons >= a.maxSites) throw new Error("CAP");
1567	      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
1568	      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) — not the
1569	      // advisory isHostnameClaimed read above — is what actually stops a co-tenant
1570	      // from committing this same server_name as their primary/subdomain/addon.
1571	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(fqdn), accountId: a.id, kind: "SUBDOMAIN" } });
1572	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
1573	    }, { isolationLevel: "Serializable" });
1574	  } catch (e) {
1575	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
1576	    if (isUniqueViolation(e)) return { error: "That hostname is already in use on Nxeon." };
1577	    return { error: "That subdomain already exists, or the request raced — try again." };
1578	  }
1579	  revalidatePath(`/dashboard/hosting/${accountId}`);
1580	  return { ok: true };
1581	}
