1594	export async function createAddonDomain(accountId: string, domain: string): Promise<HostingResult> {
1595	  const ctx = await ownedSiteAccount(accountId);
1596	  if ("error" in ctx) return { error: ctx.error };
1597	  const { a } = ctx;
1598	  const name = normalizeHostingDomain(domain);
1599	  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
1600	  if (name === a.primaryDomain) return { error: "That’s already your primary domain." };
1601	  // Cross-tenant uniqueness across ALL three hostname tables — a shared vhost keys
1602	  // on server_name, so an addon must not shadow anyone's primary, subdomain, or
1603	  // addon (audit HIGH-1: this used to omit HostingSubdomain.fqdn).
1604	  if (await isHostnameClaimed(name)) {
1605	    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
1606	  }
1607	  const { docroot } = addonDomainPaths(a.username, name);
1608	  try {
1609	    await db.$transaction(async (tx) => {
1610	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1611	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1612	      if (subs + addons >= a.maxSites) throw new Error("CAP");
1613	      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: name, docroot, status: "PENDING" } });
1614	      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) is the
1615	      // authoritative guard against another tenant committing this same
1616	      // server_name as their primary/subdomain/addon between our check and commit.
1617	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: a.id, kind: "ADDON" } });
1618	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
