1621	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
1622	    if (isUniqueViolation(e)) return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
1623	    return { error: "That domain is already added, or the request raced — try again." };
1624	  }
