"use client";

import { useState, useTransition } from "react";
import { resetRootPassword } from "@/lib/actions-server";

export function CopyText({ text, label }: { text: string; label?: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="btn-ghost px-2 py-1 text-xs"
      onClick={() => {
        void navigator.clipboard.writeText(text).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        });
      }}
    >
      {copied ? "Copied ✓" : label ?? "Copy"}
    </button>
  );
}

export function ResetPasswordButton({
  serverId,
  disabled,
  label,
}: {
  serverId: string;
  disabled?: boolean;
  label?: string;
}) {
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();
  return (
    <span className="inline-flex flex-wrap items-center gap-2">
      <button
        type="button"
        className="btn-secondary px-3 py-1 text-xs"
        disabled={pending || disabled}
        onClick={() => {
          if (
            window.confirm(
              "Reset the root password? A new strong password is generated and applied to the server. Any password-based sessions using the old password will need the new one."
            )
          ) {
            start(async () => {
              setError(null);
              const res = await resetRootPassword(serverId);
              if (res?.error) setError(res.error);
            });
          }
        }}
      >
        {pending ? "Queueing…" : label ?? "Reset root password"}
      </button>
      {error && <span className="text-xs text-red-400">{error}</span>}
    </span>
  );
}
