import { join } from "node:path";

/**
 * Where customer-uploaded website thumbnails are stored on disk. Mirrors the board
 * attachment pattern (lib/board-shared.ts BOARD_UPLOAD_DIR) — a plain directory the
 * web process can write, kept OFF the tenant tree and served only through the
 * owner-guarded /api/hosting/[id]/thumbnail route. Override with
 * NXEON_HOSTING_UPLOAD_DIR; the default sits next to the board uploads.
 */
export const HOSTING_UPLOAD_DIR = process.env.NXEON_HOSTING_UPLOAD_DIR ?? "/opt/nxeon/hosting-uploads";

/** Thumbnails are cosmetic previews — keep them small. */
export const MAX_THUMB_BYTES = 5 * 1024 * 1024;

/** Absolute path to an account's thumbnail directory (one folder per account). */
export function hostingThumbDir(accountId: string): string {
  return join(HOSTING_UPLOAD_DIR, "thumbs", accountId);
}

/** Absolute path to one stored thumbnail file. */
export function hostingThumbPath(accountId: string, storedName: string): string {
  return join(hostingThumbDir(accountId), storedName);
}

/**
 * A website's stable key ("primary" | "subdomain:<id>" | "addon:<id>") is the
 * siteRef used to key HostingWebsiteMeta. Validate the shape defensively — the value
 * arrives from the client, and it is only ever compared, never interpolated into a
 * path (the stored filename is a server-generated random hex).
 */
export function isValidSiteRef(ref: string): boolean {
  if (ref === "primary") return true;
  return /^(subdomain|addon):[a-z0-9]{20,40}$/i.test(ref);
}

