/**
 * Create a FREE, INDEPENDENT Nxeon-subdomain website — `<label>.<HOSTING_SUBDOMAIN_BASE>`
 * (e.g. `myshop.sites.nxeon.cloud`) at the BASE zone, with its OWN docroot + vhost.
 *
 * THE PRIMARY-CENTRISM FIX. The legacy `createSubdomain` nests a new site UNDER the
 * account's primaryDomain (`<label>.<primaryDomain>`), so a "second website" was
 * really a child of the first — never a true peer, and dead if the primary domain
 * wasn't pointed. This action instead provisions the free subdomain through the
 * ADDON-DOMAIN machinery: it is a HostingAddonDomain row whose `domain` is the
 * base-zone FQDN, giving it an independent docroot (`domains/<fqdn>/public_html`),
 * its own nginx server_name (taskCreateAddonDomain), and automatic HTTPS — the ONE
 * `*.<base>` wildcard cert already covers it and the wildcard A record resolves it,
 * so there is nothing for the customer to point. It counts against maxSites like any
 * other extra site, and is de-duplicated cross-tenant by the same atomic
 * UNIQUE(hostname) claim every hostname path uses. Legacy nested subdomains created
 * via createSubdomain keep working untouched (back-compat).
 */
export async function createFreeSubdomainSite(accountId: string, label: string): Promise<HostingResult> {
  const ctx = await ownedSiteAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const { a } = ctx;
  const clean = String(label ?? "").trim().toLowerCase();
  if (!isValidSubdomainLabel(clean)) {
    return { error: "Choose a subdomain of 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
  }
  // Base-zone FQDN — NOT `<label>.<primaryDomain>`. This is what makes the site an
  // independent peer instead of a child of the account's primary domain.
  const fqdn = freeSubdomainFor(clean);
  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname — try another." };
  if (fqdn === a.primaryDomain) return { error: "That’s already this plan’s primary website." };
  if (await isHostnameClaimed(fqdn)) {
    return { error: `${fqdn} is already taken — please choose another subdomain.` };
  }
  // Own docroot via the addon-domain path helper: /home/<user>/domains/<fqdn>/public_html.
  const { docroot } = addonDomainPaths(a.username, fqdn);
  try {
    await db.$transaction(async (tx) => {
      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
      if (subs + addons >= a.maxSites) throw new Error("CAP");
      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: fqdn, docroot, status: "PENDING" } });
      // Same atomic cross-tenant claim as every other hostname path (kind ADDON —
      // this IS an independent addon-style site that happens to be a free subdomain).
      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(fqdn), accountId: a.id, kind: "ADDON" } });
      // Reuse the addon provisioning task verbatim: own docroot + own vhost. Wildcard
      // SSL + the wildcard A record cover the base zone, so it goes live automatically.
      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
    }, { isolationLevel: "Serializable" });
  } catch (e) {
    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
    if (isUniqueViolation(e)) return { error: `${fqdn} is already taken — please choose another subdomain.` };
    return { error: "Couldn’t create that website, or the request raced — try again." };
  }
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

