import { NextRequest, NextResponse } from "next/server";
import { createReadStream, promises as fs } from "node:fs";
import { randomBytes } from "node:crypto";
import { Readable } from "node:stream";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { isAllowedImageMime, sniffImageMime } from "@/lib/chat-attachment";
import { hostingThumbDir, hostingThumbPath, isValidSiteRef, MAX_THUMB_BYTES } from "@/lib/hosting-thumb";

export const dynamic = "force-dynamic";

/** Owner-or-admin guard for a hosting account. Returns null when the caller may not
 *  touch it (route replies 403/404 accordingly). */
async function guard(accountId: string): Promise<{ ok: true } | { status: number; msg: string }> {
  let user;
  try {
    user = await requireUser();
  } catch {
    return { status: 403, msg: "Forbidden" };
  }
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
  if (!a) return { status: 404, msg: "Not found" };
  if (a.userId !== user.id && user.role !== "ADMIN") return { status: 403, msg: "Forbidden" };
  return { ok: true };
}

/**
 * Serve a website's customer-uploaded thumbnail. Owner-guarded (cookies ride along on
 * the <img> request). `?site=<siteRef>` selects the website. Served with the same
 * hardening as board attachments — nosniff + a locked-down CSP — so a stored image
 * can never execute as a document.
 */
export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const g = await guard(id);
  if ("status" in g) return new NextResponse(g.msg, { status: g.status });

  const siteRef = req.nextUrl.searchParams.get("site") ?? "";
  if (!isValidSiteRef(siteRef)) return new NextResponse("Bad request", { status: 400 });

  const meta = await db.hostingWebsiteMeta.findUnique({
    where: { accountId_siteRef: { accountId: id, siteRef } },
    select: { thumbName: true, thumbMime: true },
  });
  if (!meta?.thumbName) return new NextResponse("Not found", { status: 404 });

  const path = hostingThumbPath(id, meta.thumbName);
  let size: number;
  try {
    size = (await fs.stat(path)).size;
  } catch {
    return new NextResponse("Missing", { status: 404 });
  }
  const stream = createReadStream(path);
  return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
    status: 200,
    headers: {
      "Content-Type": meta.thumbMime ?? "application/octet-stream",
      "Content-Length": String(size),
      "Cache-Control": "private, max-age=60",
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "default-src 'none'; sandbox",
    },
  });
}

/**
 * Upload (or replace) a website's thumbnail. Owner-guarded. `?site=<siteRef>`. Only a
 * real raster image is accepted — verified by byte signature (never a scripted SVG),
 * exactly like the board attachment upload — and the sniffed canonical MIME is stored.
 */
export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const g = await guard(id);
  if ("status" in g) return NextResponse.json({ error: g.msg }, { status: g.status });

  const siteRef = req.nextUrl.searchParams.get("site") ?? "";
  if (!isValidSiteRef(siteRef)) return NextResponse.json({ error: "Unknown website." }, { status: 400 });

  const form = await req.formData();
  const file = form.get("file");
  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
  if (file.size > MAX_THUMB_BYTES) {
    return NextResponse.json({ error: `Image too large (max ${Math.round(MAX_THUMB_BYTES / 1024 / 1024)} MB).` }, { status: 413 });
  }

  const buf = Buffer.from(await file.arrayBuffer());
  const sniffed = sniffImageMime(buf);
  if (!sniffed || (file.type && !isAllowedImageMime(file.type)) || file.type === "image/svg+xml") {
    return NextResponse.json({ error: "Only PNG, JPEG, GIF, or WEBP images are allowed." }, { status: 400 });
  }

  const ext = sniffed === "image/png" ? ".png" : sniffed === "image/gif" ? ".gif" : sniffed === "image/webp" ? ".webp" : ".jpg";
  const storedName = `${randomBytes(12).toString("hex")}${ext}`;
  const dir = hostingThumbDir(id);
  try {
    await fs.mkdir(dir, { recursive: true });
    await fs.writeFile(hostingThumbPath(id, storedName), buf);
  } catch (e) {
    console.error("[hosting] thumbnail write failed:", e);
    return NextResponse.json(
      { error: `Couldn't save the image (${(e as NodeJS.ErrnoException)?.code ?? "write error"}).` },
      { status: 500 },
    );
  }

  // Upsert the meta row; capture the prior file so it can be unlinked after the swap.
  const prior = await db.hostingWebsiteMeta.findUnique({
    where: { accountId_siteRef: { accountId: id, siteRef } },
    select: { thumbName: true },
  });
  await db.hostingWebsiteMeta.upsert({
    where: { accountId_siteRef: { accountId: id, siteRef } },
    create: { accountId: id, siteRef, thumbName: storedName, thumbMime: sniffed },
    update: { thumbName: storedName, thumbMime: sniffed },
  });
  if (prior?.thumbName && prior.thumbName !== storedName) {
    await fs.unlink(hostingThumbPath(id, prior.thumbName)).catch(() => {});
  }

  return NextResponse.json({ ok: true, thumbnailAt: new Date().toISOString() });
}

