/**
 * Security core for live-chat image attachments.
 *
 * Everything the upload paths (customer widget route + admin server action) and
 * the serving route agree on lives here: the allow-list, the size cap, and —
 * critically — the magic-number sniffer that validates the *real bytes* rather
 * than trusting the client-declared Content-Type. SVG is intentionally absent
 * from the allow-list AND has no binary signature, so it is rejected twice over
 * (SVG can carry <script> and would enable stored XSS if ever served).
 */

/** The only image types we accept. `image/svg+xml` is deliberately excluded. */
export const ALLOWED_IMAGE_MIME = [
  "image/png",
  "image/jpeg",
  "image/gif",
  "image/webp",
] as const;

export type AllowedImageMime = (typeof ALLOWED_IMAGE_MIME)[number];

/** Hard cap: 5 MB. Enforced server-side regardless of any client check. */
export const MAX_ATTACHMENT_BYTES = 5 * 1024 * 1024;

/** `accept` attribute value shared by the file inputs. */
export const ACCEPT_ATTR = ALLOWED_IMAGE_MIME.join(",");

export function isAllowedImageMime(mime: string): mime is AllowedImageMime {
  return (ALLOWED_IMAGE_MIME as readonly string[]).includes(mime);
}

/**
 * Detect the true image type from the leading bytes (file signature). Returns
 * the canonical MIME for a recognised, allowed image, or `null` for anything
 * else — including SVG, HTML, scripts, or a JPEG renamed to .png. Callers must
 * treat `null` as "reject".
 */
export function sniffImageMime(buf: Uint8Array): AllowedImageMime | null {
  if (buf.length < 12) return null;
  const b = buf;

  // PNG: 89 50 4E 47 0D 0A 1A 0A
  if (
    b[0] === 0x89 &&
    b[1] === 0x50 &&
    b[2] === 0x4e &&
    b[3] === 0x47 &&
    b[4] === 0x0d &&
    b[5] === 0x0a &&
    b[6] === 0x1a &&
    b[7] === 0x0a
  ) {
    return "image/png";
  }

