"use client";
/* eslint-disable @next/next/no-img-element */

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import {
  getHostingAccount,
  revealHostingSftpPassword,
  recheckHostingHealth,
  renameHostingAccount,
  listWebsites,
  listHostingDatabases,
  listHostingBackups,
  listHostingSubdomains,
  listHostingAddonDomains,
  listHostingTaskLog,
  installWordPress,
  installApp,
  listAppCatalog,
  setPrimaryHostingDomain,
  deleteSubdomain,
  deleteAddonDomain,
  createFreeSubdomainSite,
  createAddonDomain,
  checkHostingSubdomain,
  removeHostingThumbnail,
  type HostingAccountView,
  type HostingWebsiteView,
  type SiteTarget,
} from "@/lib/actions-hosting";
import { getHostingEmailStatus } from "@/lib/hosting-email";
import { Badge, StatCard, StatusDot, EmptyState, fmtBytes, timeAgo } from "@/components/ui/primitives";
import { Icon, type IconName } from "@/components/ui/Icon";
import { AppLogo } from "@/components/ui/AppLogo";
import { QuotaTile } from "./shared";
import { AppCredentials } from "./AppCredentials";
import { FileManager } from "./FileManager";
import { Backups } from "./Backups";
import { DatabasesPanel } from "./DatabasesPanel";
import { PhpSwitcher } from "./PhpSwitcher";
import { SubdomainsPanel } from "./SubdomainsPanel";
import { AddonDomainsPanel } from "./AddonDomainsPanel";
import { CronPanel } from "./CronPanel";
import { EmailTab } from "./EmailTab";
import { HostingUpgradePanel } from "./HostingUpgradePanel";

/* ==========================================================================
 * Hosting console — the plan-as-workspace shell, rebuilt on the portal's real
 * design system (components/ui/primitives + Icon + AppLogo + the global .card/.btn
 * utility classes). NO emojis anywhere: every glyph is an inline-SVG <Icon> or a
 * brand <AppLogo>.
 *
 * Two views, both URL-addressable so links survive a refresh:
 *   • PLAN CONSOLE (default)  — header + resource stat-cards (primary nav) + a
 *     website GRID whose cards carry a real thumbnail/preview + Activity / Plan /
 *     Usage. Plan-scoped SECTIONS (Databases, Email, Backups, Domains, Files, Cron,
 *     Logs, Settings) reuse the existing panels verbatim.  URL: `?tab=<section>`.
 *   • WEBSITE DETAIL          — scoped to ONE website, a fully self-contained site
 *     (its own domain, app, files, SSL, stats) with NO primary-centric framing.
 *     URL: `?site=<id|primary>&stab=<subtab>`.
 *
 * Every read/mutation is a real ownership-guarded server action — no mock data.
 * ======================================================================== */

const SECTIONS: [key: string, label: string, icon: IconName][] = [
  ["databases", "Databases", "database"],
  ["email", "Email", "mail"],
  ["backups", "Backups", "clock"],
  ["domains", "Domains & SSL", "globe"],
  ["files", "File Manager", "folder"],
  ["cron", "Cron", "refresh"],
  ["logs", "Logs", "activity"],
  ["settings", "Settings", "settings"],
];
const SECTION_KEYS = SECTIONS.map(([k]) => k);

const SITE_TABS: [key: string, label: string][] = [
  ["overview", "Overview"],
  ["app", "App"],
  ["files", "Files"],
  ["domains", "Domains & SSL"],
  ["email", "Email"],
  ["databases", "Databases"],
  ["logs", "Logs"],
  ["settings", "Settings"],
];
const SITE_TAB_KEYS = SITE_TABS.map(([k]) => k);

type Counts = {
  dbs: number;
  backups: number;
  emailUsed: number;
  emailCap: number | null;
  subs: number;
  addons: number;
};

/* ---- app-visual mapping: an installed-app label → a brand logo or a clean icon --- */

const APP_LOGO_MATCHERS: [needle: string, family: string][] = [
  ["woocommerce", "woocommerce"],
  ["wordpress", "wordpress"],
  ["ghost", "ghost"],
  ["nextcloud", "nextcloud"],
  ["gitea", "gitea"],
  ["grafana", "grafana"],
  ["jellyfin", "jellyfin"],
  ["portainer", "portainer"],
];

function appVisual(installedApp: string | null): { logo?: string; icon: IconName } {
  const s = (installedApp ?? "").toLowerCase();
  if (!s) return { icon: "globe" }; // static site / no app
  for (const [needle, family] of APP_LOGO_MATCHERS) if (s.includes(needle)) return { logo: family, icon: "grid" };
  return { icon: "grid" };
}

/** A square app badge: the real brand logo when known, else a tasteful icon chip. */
function AppBadge({ installedApp, size = 32 }: { installedApp: string | null; size?: number }) {
  const v = appVisual(installedApp);
  if (v.logo) return <AppLogo family={v.logo} name={installedApp ?? undefined} size={size} />;
  return (
    <span
      className="flex items-center justify-center rounded-lg border border-white/10 bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-brand-200"
      style={{ width: size, height: size, minWidth: size }}
    >
      <Icon name={v.icon} size={Math.round(size * 0.52)} />
    </span>
  );
}

/** A website's thumbnail: the customer's uploaded preview, or a branded placeholder
 *  (subtle gradient + app logo + hostname — never an emoji). */
function Thumbnail({ accountId, site }: { accountId: string; site: HostingWebsiteView }) {
  if (site.thumbnailAt) {
    const src = `/api/hosting/${accountId}/thumbnail?site=${encodeURIComponent(site.key)}&v=${encodeURIComponent(site.thumbnailAt)}`;
    return <img src={src} alt={`${site.hostname} preview`} className="h-full w-full object-cover" />;
  }
  return (
    <div className="relative flex h-full w-full items-center justify-center overflow-hidden bg-gradient-to-br from-navy-900 via-brand-500/10 to-accent-blue/20">
      <div
        className="absolute inset-0 opacity-[0.12]"
        style={{ backgroundImage: "radial-gradient(circle at 1px 1px, rgba(255,255,255,0.6) 1px, transparent 0)", backgroundSize: "16px 16px" }}
      />
      <div className="relative flex flex-col items-center gap-2 px-3 text-center">
        <AppBadge installedApp={site.installedApp} size={40} />
        <span className="max-w-full truncate font-mono text-xs text-slate-300">{site.hostname}</span>
      </div>
    </div>
  );
}

export function HostingConsole({
  account,
  initialTab,
  initialPath,
  initialSite,
  initialSiteTab,
}: {
  account: HostingAccountView;
  initialTab?: string;
  initialPath?: string;
  initialSite?: string;
  initialSiteTab?: string;
}) {
  const active = account.status === "ACTIVE";

  const [siteParam, setSiteParam] = useState<string | undefined>(initialSite);
  const [siteTab, setSiteTab] = useState<string>(
    initialSiteTab && SITE_TAB_KEYS.includes(initialSiteTab) ? initialSiteTab : "overview",
  );
  const [section, setSection] = useState<string>(
    initialTab && SECTION_KEYS.includes(initialTab) ? initialTab : "console",
  );

  const [sites, setSites] = useState<HostingWebsiteView[] | null>(null);
  const refreshSites = useCallback(() => {
    if (!active) { setSites([]); return; }
    listWebsites(account.id).then(setSites).catch(() => setSites([]));
  }, [account.id, active]);
  useEffect(() => { refreshSites(); }, [refreshSites]);

  function pushUrl(params: Record<string, string | undefined>) {
    const qs = new URLSearchParams();
    for (const [k, v] of Object.entries(params)) if (v) qs.set(k, v);
    const s = qs.toString();
    window.history.replaceState(null, "", s ? `?${s}` : window.location.pathname);
  }
  const goHub = useCallback(() => {
    setSiteParam(undefined); setSection("console"); pushUrl({}); window.scrollTo(0, 0);
  }, []);
  const goSection = useCallback((sec: string) => {
    setSiteParam(undefined); setSection(sec); pushUrl({ tab: sec }); window.scrollTo(0, 0);
  }, []);
  const openSite = useCallback((param: string) => {
    setSiteParam(param); setSiteTab("overview"); pushUrl({ site: param, stab: "overview" }); window.scrollTo(0, 0);
  }, []);
  const goSiteTab = useCallback((t: string) => {
    setSiteTab(t); setSiteParam((p) => { pushUrl({ site: p, stab: t }); return p; });
  }, []);

  return (
    <div>
      {siteParam ? (
        <WebsiteDetail
          account={account}
          sites={sites}
          siteParam={siteParam}
          siteTab={siteTab}
          onHub={goHub}
          onSiteTab={goSiteTab}
          onSection={goSection}
          onSitesChanged={refreshSites}
        />
      ) : section === "console" ? (
        <PlanConsole
          account={account}
          sites={sites}
          onOpenSite={openSite}
          onSection={goSection}
          onSitesChanged={refreshSites}
        />
      ) : (
        <PlanSection account={account} section={section} initialPath={initialPath} onHub={goHub} onSection={goSection} />
      )}
    </div>
  );
}

/* ============================================================ plan header === */

function ConsoleHeader({ account }: { account: HostingAccountView }) {
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(account.name ?? "");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  async function save() {
    setBusy(true); setErr("");
    const r = await renameHostingAccount(account.id, value);
    setBusy(false);
    if (r.error) { setErr(r.error); return; }
    setEditing(false);
    window.location.reload();
  }

  return (
    <div>
      <div className="flex flex-wrap items-center gap-3">
        {editing ? (
          <div className="flex flex-wrap items-center gap-2">
            <input
              className="input max-w-[280px] text-lg font-semibold"
              value={value}
              maxLength={60}
              autoFocus
              disabled={busy}
              placeholder={`My ${account.planName} workspace`}
              onChange={(e) => setValue(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") save(); if (e.key === "Escape") setEditing(false); }}
            />
            <button className="btn-primary px-3 py-1.5 text-sm" disabled={busy} onClick={save}>{busy ? "Saving…" : "Save"}</button>
            <button className="btn-secondary px-3 py-1.5 text-sm" disabled={busy} onClick={() => { setEditing(false); setValue(account.name ?? ""); }}>Cancel</button>
          </div>
        ) : (
          <>
            <h1 className="page-title">{account.displayName}</h1>
            <button
              type="button"
              title="Rename this plan"
              onClick={() => setEditing(true)}
              className="btn-ghost inline-flex h-8 w-8 items-center justify-center p-0 text-slate-400 hover:text-white"
            >
              <Icon name="pencil" size={15} />
            </button>
            <Badge tone="brand">{account.planName}</Badge>
            <StatusDot status={account.status} />
          </>
        )}
      </div>
      {err && <p className="mt-2 text-sm text-red-400">{err}</p>}
      <div className="mt-2 flex flex-wrap items-center gap-2">
        <a
          href={account.sslActive ? `https://${account.primaryDomain}` : `http://${account.primaryDomain}`}
          target="_blank"
          rel="noreferrer"
          className="inline-flex items-center gap-1.5 rounded-md border border-white/[0.08] bg-white/[0.03] px-2 py-0.5 font-mono text-xs text-slate-300 hover:text-white"
        >
          {account.primaryDomain}
          <Icon name="external-link" size={12} />
        </a>
        {account.sslActive && <Badge tone="green">HTTPS</Badge>}
        <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">All hosting</a>
      </div>
    </div>
  );
}

/* =========================================================== plan console === */

function PlanConsole({
  account,
  sites,
  onOpenSite,
  onSection,
  onSitesChanged,
}: {
  account: HostingAccountView;
  sites: HostingWebsiteView[] | null;
  onOpenSite: (param: string) => void;
  onSection: (sec: string) => void;
  onSitesChanged: () => void;
}) {
  const active = account.status === "ACTIVE";
  const gridRef = useRef<HTMLDivElement>(null);
  const [counts, setCounts] = useState<Counts | null>(null);
  const [adding, setAdding] = useState(false);

  useEffect(() => {
    if (!active) return;
    let live = true;
    Promise.all([
      listHostingDatabases(account.id).catch(() => []),
      listHostingBackups(account.id).catch(() => []),
      listHostingSubdomains(account.id).catch(() => []),
      listHostingAddonDomains(account.id).catch(() => []),
      getHostingEmailStatus(account.id).catch(() => null),
    ]).then(([dbs, backups, subs, addons, email]) => {
      if (!live) return;
      setCounts({
        dbs: dbs.length,
        backups: backups.length,
        emailUsed: email?.bundled?.mailboxes.length ?? 0,
        emailCap: email?.includedMailboxes ?? null,
        subs: subs.filter((s) => s.status !== "DELETING").length,
        addons: addons.filter((d) => d.status !== "DELETING").length,
      });
    });
    return () => { live = false; };
  }, [account.id, active]);

  const siteCount = sites?.length ?? 0;
  const siteCap = 1 + account.maxSites; // primary + extra sites
  const diskGB = Math.round(account.diskQuotaMB / 1024);
  const usedGB = account.diskUsedMB != null ? account.diskUsedMB / 1024 : null;

  function scrollToGrid() {
    gridRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  return (
    <div>
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0 flex-1"><ConsoleHeader account={account} /></div>
        {active && (
          <div className="flex flex-wrap items-center gap-2">
            <button className="btn-secondary inline-flex items-center gap-1.5 text-sm" onClick={() => onSection("settings")}>
              <Icon name="arrow-up" size={15} /> Upgrade plan
            </button>
            <button className="btn-secondary inline-flex items-center gap-1.5 text-sm" onClick={() => onSection("settings")}>
              <Icon name="hard-drive" size={15} /> Upgrade storage
            </button>
            <button className="btn-primary inline-flex items-center gap-1.5 text-sm" onClick={() => setAdding(true)}>
              <Icon name="plus" size={15} /> Add website
            </button>
          </div>
        )}
      </div>

      <StatusBanner account={account} />

      {active ? (
        <>
          {/* Resource stat-cards — the primary navigation, from the design system. */}
          <div className="mt-6 grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-5">
            <button type="button" onClick={scrollToGrid} className="text-left">
              <StatCard label="Websites" value={`${siteCount} / ${siteCap}`} icon={<Icon name="globe" size={18} />} />
            </button>
            <StatCard
              label="Storage"
              value={usedGB != null ? `${usedGB.toFixed(usedGB < 1 ? 2 : 1)} / ${diskGB} GB` : `${diskGB} GB`}
              icon={<Icon name="hard-drive" size={18} />}
              href={`/dashboard/hosting/${account.id}?tab=settings`}
            />
            <StatCard
              label="Databases"
              value={account.maxDatabases > 0 ? `${counts?.dbs ?? 0} / ${account.maxDatabases}` : "—"}
              icon={<Icon name="database" size={18} />}
              href={`/dashboard/hosting/${account.id}?tab=databases`}
            />
            <StatCard
              label="Emails"
              value={counts?.emailCap != null ? `${counts.emailUsed} / ${counts.emailCap}` : String(counts?.emailUsed ?? 0)}
              icon={<Icon name="mail" size={18} />}
              href={`/dashboard/hosting/${account.id}?tab=email`}
            />
            <StatCard
              label="Backups"
              value={String(counts?.backups ?? 0)}
              icon={<Icon name="clock" size={18} />}
              href={`/dashboard/hosting/${account.id}?tab=backups`}
            />
          </div>

          <div className="mt-8 grid grid-cols-1 gap-6 xl:grid-cols-[1fr_320px] xl:items-start">
            <div className="min-w-0">
              <div id="websites" className="mb-3 flex flex-wrap items-center justify-between gap-2">
                <h2 className="text-base font-semibold">Websites</h2>
                <WebsiteSwitcher sites={sites ?? []} onPick={onOpenSite} />
              </div>
              <div ref={gridRef} className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                {sites === null ? (
                  <p className="text-sm text-slate-500">Loading websites…</p>
                ) : (
                  <>
                    {sites.map((w) => (
                      <WebsiteCard
                        key={w.key}
                        site={w}
                        accountId={account.id}
                        onManage={() => onOpenSite(w.id ?? "primary")}
                        onOpenSite={onOpenSite}
                        onSitesChanged={onSitesChanged}
                      />
                    ))}
                    <button
                      type="button"
                      onClick={() => setAdding(true)}
                      className="flex min-h-[220px] flex-col items-center justify-center gap-2 rounded-2xl border border-dashed border-white/15 p-6 text-center text-slate-400 transition-colors hover:border-brand-400 hover:text-white"
                    >
                      <span className="grid h-11 w-11 place-items-center rounded-xl border border-brand-500/30 bg-brand-500/10 text-brand-300">
                        <Icon name="plus" size={20} />
                      </span>
                      <span className="font-semibold">Add new website</span>
                      <span className="text-xs text-slate-500">A free Nxeon subdomain or your own domain — each an independent site</span>
                    </button>
                  </>
                )}
              </div>

              <div className="mt-6 grid grid-cols-1 gap-4 lg:grid-cols-2">
                <ActivityCard accountId={account.id} onSection={onSection} />
                <PlanInfoCard account={account} counts={counts} siteCount={siteCount} siteCap={siteCap} onSection={onSection} />
              </div>

              <ResourceUsageCard account={account} counts={counts} />

              <div className="mt-6"><AppCredentials accountId={account.id} /></div>
            </div>

            {/* Slim right rail: connection + go-live status (non-redundant only). */}
            <aside className="flex flex-col gap-4">
              <ConnectionCard account={account} />
            </aside>
          </div>
        </>
      ) : (
        <div className="mt-6"><NotReady /></div>
      )}

      {adding && (
        <AddWebsiteModal account={account} onClose={() => setAdding(false)} onCreated={() => { setAdding(false); onSitesChanged(); }} />
      )}
    </div>
  );
}

/* --------------------------------------------------------- website cards --- */

function targetOf(w: HostingWebsiteView): SiteTarget {
  if (w.kind === "subdomain" && w.id) return { kind: "subdomain", id: w.id };
  if (w.kind === "addon" && w.id) return { kind: "addon", id: w.id };
  return { kind: "primary" };
}

/** A short, non-primary-centric type label. A free subdomain reads as such (not
 *  "Addon domain"); the primary badge is a small marker, not the site's identity. */
function kindLabel(w: HostingWebsiteView): string {
  if (w.kind === "primary") return "Primary";
  if (w.isFreeSubdomain) return "Free subdomain";
  if (w.kind === "subdomain") return "Subdomain";
  return "Custom domain";
}

function WebsiteCard({
  site, accountId, onManage, onOpenSite, onSitesChanged,
}: {
  site: HostingWebsiteView; accountId: string; onManage: () => void;
  onOpenSite: (p: string) => void; onSitesChanged: () => void;
}) {
  const [menu, setMenu] = useState(false);
  const [busy, setBusy] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const settling = site.status === "PENDING" || site.status === "DELETING";

  useEffect(() => {
    function onDoc(e: MouseEvent) { if (ref.current && !ref.current.contains(e.target as Node)) setMenu(false); }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  async function promote() {
    if (!site.id) return;
    setMenu(false);
    if (!confirm(`Make ${site.hostname} the main domain for this plan? Your current main website answers on ${site.hostname}, and the old address keeps working as an alias.`)) return;
    setBusy(true);
    const r = await setPrimaryHostingDomain(accountId, site.id);
    setBusy(false);
    if (r.error) alert(r.error); else onSitesChanged();
  }
  async function remove() {
    if (!site.id) return;
    setMenu(false);
    if (!confirm(`Delete ${site.hostname}? Its files will be removed.`)) return;
    setBusy(true);
    const r = site.kind === "subdomain" ? await deleteSubdomain(site.id) : await deleteAddonDomain(site.id);
    setBusy(false);
    if (r.error) alert(r.error); else onSitesChanged();
  }

  return (
    <div className="card card-hover overflow-hidden p-0">
      <div className="relative aspect-[16/9] w-full border-b border-white/[0.06]">
        <Thumbnail accountId={accountId} site={site} />
        <div className="absolute left-2.5 top-2.5 flex flex-wrap gap-1.5">
          {site.status === "ACTIVE" ? <Badge tone="green">Active</Badge> : <span className="rounded-full bg-navy-900/80 px-1.5 py-0.5 backdrop-blur"><StatusDot status={site.status} /></span>}
