function AddFreeSubdomain({ account, onCreated }: { account: HostingAccountView; onCreated: () => void }) {
  const [label, setLabel] = useState("");
  const [check, setCheck] = useState<{ available: boolean; fqdn: string; reason?: string } | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  useEffect(() => {
    const l = label.trim().toLowerCase();
    if (!l) { setCheck(null); return; }
    let live = true;
    const t = setTimeout(() => {
      checkHostingSubdomain(l).then((r) => { if (live) setCheck(r); }).catch(() => {});
    }, 350);
    return () => { live = false; clearTimeout(t); };
  }, [label]);

  async function create() {
    setBusy(true); setErr("");
    const r = await createFreeSubdomainSite(account.id, label.trim().toLowerCase());
    setBusy(false);
    if (r.error) { setErr(r.error); return; }
    onCreated();
  }

  const ok = check?.available === true;
  return (
    <div>
      <label className="label">Choose a subdomain</label>
      <div className="mt-1 flex items-stretch overflow-hidden rounded-lg border border-white/[0.1] bg-white/[0.03] focus-within:border-brand-400">
        <input
          className="min-w-0 flex-1 bg-transparent px-3 py-2 text-sm text-slate-100 placeholder:text-slate-500 focus:outline-none"
          placeholder="myshop"
          value={label}
          maxLength={32}
          autoFocus
          onChange={(e) => setLabel(e.target.value.replace(/[^a-zA-Z0-9-]/g, ""))}
          onKeyDown={(e) => { if (e.key === "Enter" && ok && !busy) create(); }}
        />
        <span className="flex items-center whitespace-nowrap border-l border-white/[0.08] bg-white/[0.02] px-3 font-mono text-sm text-slate-400">.{account.subdomainBase}</span>
      </div>
      {label.trim() && check && (
        <p className={`mt-2 flex items-center gap-1.5 text-xs ${ok ? "text-emerald-300" : "text-amber-300"}`}>
          <Icon name={ok ? "check" : "clock"} size={13} />
          {ok ? `${check.fqdn} is available` : check.reason ?? "Checking…"}
        </p>
      )}
      <p className="mt-3 text-xs text-slate-500">A free subdomain resolves and gets HTTPS automatically — there is nothing to point. It becomes its own independent website with its own files and app.</p>
      {err && <p className="mt-2 text-sm text-red-400">{err}</p>}
      <button className="btn-primary mt-4 w-full text-sm" disabled={busy || !ok} onClick={create}>{busy ? "Creating…" : "Create website"}</button>
    </div>
  );
}

function AddOwnDomain({ account, onCreated }: { account: HostingAccountView; onCreated: () => void }) {
  const [domain, setDomain] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  async function create() {
    setBusy(true); setErr("");
    const r = await createAddonDomain(account.id, domain.trim());
    setBusy(false);
    if (r.error) { setErr(r.error); return; }
    onCreated();
  }

  return (
    <div>
      <label className="label">Your domain</label>
      <input
        className="input mt-1 w-full text-sm"
        placeholder="example.com"
        value={domain}
        autoFocus
        onChange={(e) => setDomain(e.target.value)}
        onKeyDown={(e) => { if (e.key === "Enter" && domain.trim() && !busy) create(); }}
      />
      <div className="mt-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5 text-xs text-slate-400">
        Point the domain at us with an <span className="font-mono text-slate-200">A</span> record to{" "}
        <span className="font-mono text-brand-200">{account.pointToA}</span>. HTTPS is issued automatically once it resolves.
      </div>
      {err && <p className="mt-2 text-sm text-red-400">{err}</p>}
      <button className="btn-primary mt-4 w-full text-sm" disabled={busy || !domain.trim()} onClick={create}>{busy ? "Adding…" : "Add website"}</button>
    </div>
  );
}

/* ------------------------------------------------------- website switcher --- */

function WebsiteSwitcher({ sites, onPick }: { sites: HostingWebsiteView[]; onPick: (siteParam: string) => void }) {
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(false);
  const boxRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onDoc(e: MouseEvent) { if (boxRef.current && !boxRef.current.contains(e.target as Node)) setOpen(false); }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  const needle = q.trim().toLowerCase();
  const matches = needle ? sites.filter((s) => s.hostname.toLowerCase().includes(needle)) : sites;

  return (
    <div ref={boxRef} className="relative w-full max-w-xs">
      <div className="flex items-center gap-2 rounded-xl border border-white/[0.08] bg-navy-900/70 px-3 py-1.5 backdrop-blur-md">
        <Icon name="search" size={16} className="shrink-0 text-slate-500" />
        <input
          className="w-full bg-transparent text-sm text-slate-100 placeholder:text-slate-500 focus:outline-none"
          placeholder={`Search websites${sites.length ? ` (${sites.length})` : ""}…`}
          value={q}
          onFocus={() => setOpen(true)}
          onChange={(e) => { setQ(e.target.value); setOpen(true); }}
        />
      </div>
      {open && (
        <div className="absolute z-20 mt-1 max-h-72 w-full overflow-auto rounded-xl border border-white/[0.08] bg-navy-900/95 p-1 shadow-xl backdrop-blur-md">
          {matches.length === 0 ? (
            <p className="px-3 py-2 text-sm text-slate-500">No matching websites.</p>
          ) : (
            matches.map((w) => (
              <button
                key={w.key}
                type="button"
                onMouseDown={(e) => { e.preventDefault(); onPick(w.id ?? "primary"); setOpen(false); setQ(""); }}
                className="flex w-full items-center justify-between gap-2 rounded-lg px-3 py-2 text-left hover:bg-white/[0.05]"
              >
                <span className="min-w-0 truncate font-mono text-sm text-slate-100">{w.hostname}</span>
                <Badge tone={w.kind === "primary" ? "brand" : "slate"}>{kindLabel(w)}</Badge>
              </button>
            ))
          )}
        </div>
      )}
    </div>
  );
}

