const LOG_LABELS: Record<string, string> = {
  PHP_SWITCH: "PHP version change", WORDPRESS_INSTALL: "WordPress install", APP_INSTALL: "App install",
  BACKUP: "Backup", RESTORE: "Restore", CREATE_SUBDOMAIN: "Subdomain created", DELETE_SUBDOMAIN: "Subdomain removed",
  CREATE_ADDON_DOMAIN: "Website created", DELETE_ADDON_DOMAIN: "Website removed", CREATE_CRON: "Cron job created",
  DELETE_CRON: "Cron job removed", ENSURE_DBMGR: "Database manager", APPLY_PLAN_LIMITS: "Plan update",
  SET_PRIMARY_DOMAIN: "Main domain change", RESET_DB_PASSWORD: "Database password reset",
};

type LogRow = { id: string; kind: string; status: string; error: string | null; createdAt: string; updatedAt: string };

function useTaskLog(accountId: string) {
  const [rows, setRows] = useState<LogRow[] | null>(null);
  useEffect(() => {
    let stop = false;
    const load = () => listHostingTaskLog(accountId).then((r) => { if (!stop) setRows(r); }).catch(() => { if (!stop) setRows([]); });
    load();
    const t = setInterval(load, 8000);
    return () => { stop = true; clearInterval(t); };
  }, [accountId]);
  return rows;
}

function ActivityCard({ accountId, onSection }: { accountId: string; onSection: (s: string) => void }) {
  const rows = useTaskLog(accountId);
  return (
    <div className="card">
