        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------- connection rail --- */

function ConnectionCard({ account }: { account: HostingAccountView }) {
  const [a, setA] = useState(account);
  const [sftpPw, setSftpPw] = useState<string | null>(null);
  const [recheckBusy, setRecheckBusy] = useState(false);

  const active = a.status === "ACTIVE";

  useEffect(() => {
    if (!active || a.sslActive) return;
    const t = setInterval(() => { getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {}); }, 15000);
    return () => clearInterval(t);
  }, [a.id, active, a.sslActive]);

  async function recheck() {
    setRecheckBusy(true);
    const r = await recheckHostingHealth(a.id);
    if (r.error) { alert(r.error); setRecheckBusy(false); return; }
    let tries = 0;
    const poll = setInterval(() => {
      tries++;
      getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {});
      if (tries >= 9) { clearInterval(poll); setRecheckBusy(false); }
    }, 5000);
  }

  async function reveal() {
    const res = await revealHostingSftpPassword(a.id);
    if (res.password) setSftpPw(res.password); else if (res.error) alert(res.error);
  }

  if (!active) return null;

  return (
    <div className="card">
      <div className="mb-3 flex items-center justify-between gap-2">
        <h3 className="flex items-center gap-2 font-semibold">
          <Icon name="globe" size={16} className="text-brand-300" /> {a.isFreeSubdomain ? "Your website" : "Point your domain"}
        </h3>
        <button type="button" className="btn-secondary px-2.5 py-1 text-xs" disabled={recheckBusy} onClick={recheck}>
          {recheckBusy ? "Checking…" : a.sslActive ? "Check now" : a.isFreeSubdomain ? "Refresh" : "Go live"}
        </button>
      </div>
      {!a.isFreeSubdomain && !a.sslActive && (
        <p className="mb-2 text-xs text-slate-400">
          Create an <span className="font-mono text-slate-200">A</span> record for <span className="font-mono text-slate-200">{a.primaryDomain}</span> → <span className="font-mono text-brand-200">{a.pointToA}</span>
          {a.pointToCname && <> (or a <span className="font-mono text-slate-200">CNAME</span> to <span className="font-mono text-slate-200">{a.pointToCname}</span>)</>}.
        </p>
      )}
      <DnsStepper account={a} />
      <div className="mt-4 border-t border-white/[0.06] pt-3">
        <p className="mb-1 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-slate-500"><Icon name="key" size={13} /> SFTP</p>
        <p className="text-sm text-slate-400"><span className="font-mono text-slate-200">{a.username}</span>@{a.pointToA}</p>
        {sftpPw ? (
          <p className="mt-1 break-all font-mono text-sm text-brand-200">{sftpPw}</p>
        ) : (
          <button className="mt-1 text-xs text-brand-300 hover:underline" onClick={reveal}>show password</button>
        )}
      </div>
    </div>
  );
}

/* ----------------------------------------------------------- DNS stepper --- */

function DnsStepper({ account }: { account: HostingAccountView }) {
  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
  const verified = account.sslActive && account.serveHttpsOk !== false;
  const state: "verified" | "issuing" | "dns" | "pending" = verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
  const free = account.isFreeSubdomain;
  const steps = [
    { label: free ? "DNS ready" : "Point domain", done: true },
    { label: "Site live", done: state === "issuing" || state === "verified" },
    { label: "HTTPS verified", done: state === "verified" },
  ];
  const headline =
    account.healthNote ??
    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
  const tone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
  return (
    <div>
      <div className="flex items-center">
        {steps.map((s, i) => (
          <div key={s.label} className="flex flex-1 items-center last:flex-none">
            <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
              {s.done ? <Icon name="check" size={13} /> : i + 1}
            </span>
            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
          </div>
        ))}
      </div>
      <div className="mt-1.5 flex items-start justify-between text-[11px]">
        {steps.map((s) => (
          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
          </div>
        ))}
      </div>
      <p className={`mt-2 text-xs font-medium ${tone}`}>{headline}</p>
    </div>
  );
}

/* ---------------------------------------------------------- status banner --- */

function StatusBanner({ account }: { account: HostingAccountView }) {
  if (account.status === "FAILED") {
    return <div className="mt-4 card border-red-500/30 text-sm text-red-300">Setup failed{account.error ? `: ${account.error}` : ""}. Retry from the hosting list.</div>;
  }
  if (account.status === "PENDING" || account.status === "PROVISIONING") {
    return <div className="mt-4 card border-amber-500/30 text-sm text-amber-200">We’re setting up your account — this usually takes under a minute. Refresh to see it come online.</div>;
  }
  return null;
}

