function PlanSection({
  account, section, initialPath, onHub, onSection,
}: {
  account: HostingAccountView; section: string; initialPath?: string; onHub: () => void; onSection: (s: string) => void;
}) {
  const active = account.status === "ACTIVE";
  const sectionLabel = SECTIONS.find(([k]) => k === section)?.[1] ?? "Section";

  let body: ReactNode;
  if (!active && section !== "settings") {
    body = <NotReady />;
  } else {
    switch (section) {
      case "databases": body = <DatabasesPanel accountId={account.id} username={account.username} maxDatabases={account.maxDatabases} />; break;
      case "email": body = <EmailTab account={account} />; break;
      case "backups": body = <Backups accountId={account.id} />; break;
      case "domains": body = <DomainsSection account={account} />; break;
      case "files": body = <FileManager accountId={account.id} initialPath={initialPath} />; break;
      case "cron": body = <CronPanel accountId={account.id} username={account.username} />; break;
      case "logs": body = <LogsPanel accountId={account.id} />; break;
      case "settings": body = <SettingsSection account={account} />; break;
      default: body = <NotReady />;
    }
  }

  return (
    <div>
      <div className="mb-4"><ConsoleHeader account={account} /></div>
      <SectionNav section={section} onHub={onHub} onSection={onSection} />
      <p className="mb-4 text-xs text-slate-500">Plan · <span className="text-slate-300">{sectionLabel}</span> — scoped to {account.displayName}.</p>
      <div className="animate-fade-up">{body}</div>
    </div>
  );
}

