/* ========================================================= website detail === */

function WebsiteDetail({
  account, sites, siteParam, siteTab, onHub, onSiteTab, onSection, onSitesChanged,
}: {
  account: HostingAccountView;
  sites: HostingWebsiteView[] | null;
  siteParam: string;
  siteTab: string;
  onHub: () => void;
  onSiteTab: (t: string) => void;
  onSection: (s: string) => void;
  onSitesChanged: () => void;
}) {
  const site = sites?.find((s) => (s.id ?? "primary") === siteParam) ?? null;

  if (sites === null) return <div className="card py-12 text-center text-sm text-slate-500">Loading website…</div>;
  if (!site) {
    return (
      <div className="card py-12 text-center">
        <p className="text-sm text-slate-400">That website is no longer on this plan.</p>
        <button className="btn-secondary mt-4 text-sm" onClick={onHub}>Back to console</button>
      </div>
    );
  }

  let body: ReactNode;
  switch (siteTab) {
    case "app": body = <SiteAppTab account={account} site={site} onSitesChanged={onSitesChanged} />; break;
    case "files": body = <FileManager accountId={account.id} initialPath={site.fileManagerPath} />; break;
    case "domains": body = <SiteDomainsTab account={account} site={site} onSection={onSection} onSitesChanged={onSitesChanged} />; break;
    case "email": body = <ManagedAtPlan section="email" label="Email" onSection={onSection} note="Mailboxes are provisioned per plan on a domain you choose (which can be this website's domain). Manage them in the plan Email section." />; break;
    case "databases": body = <ManagedAtPlan section="databases" label="Databases" onSection={onSection} note="Databases belong to the plan — an app on any site can connect to any of them. Manage them in the plan Databases section." />; break;
    case "logs": body = <LogsPanel accountId={account.id} />; break;
    case "settings": body = <SiteSettingsTab account={account} site={site} onSection={onSection} onSitesChanged={onSitesChanged} onHub={onHub} />; break;
    default: body = <SiteOverviewTab account={account} site={site} onSiteTab={onSiteTab} onSection={onSection} onSitesChanged={onSitesChanged} />;
  }

  return (
    <div>
      <div className="mb-3 flex items-center gap-1.5 text-xs text-slate-500">
        <button type="button" className="hover:text-slate-300" onClick={onHub}>{account.displayName}</button>
        <Icon name="chevron-right" size={13} />
        <span className="font-mono text-slate-300">{site.hostname}</span>
      </div>

      <div className="mb-5 flex flex-wrap items-center gap-4">
        <AppBadge installedApp={site.installedApp} size={52} />
        <div className="min-w-0">
          <h1 className="font-mono text-xl font-semibold tracking-tight">{site.hostname}</h1>
          <div className="mt-1.5 flex flex-wrap gap-2">
            {site.status === "ACTIVE" ? <Badge tone="green">Active</Badge> : <span><StatusDot status={site.status} /></span>}
            {site.sslActive ? <Badge tone="green">HTTPS</Badge> : <Badge tone="amber">HTTP</Badge>}
            <Badge tone="slate">{kindLabel(site)}</Badge>
            {site.installedApp && <Badge tone="brand">{site.installedApp}</Badge>}
          </div>
        </div>
        <div className="ml-auto flex flex-wrap gap-2">
          <a href={site.sslActive ? `https://${site.hostname}` : `http://${site.hostname}`} target="_blank" rel="noreferrer" className="btn-secondary inline-flex items-center gap-1.5 text-sm"><Icon name="external-link" size={15} /> Visit</a>
          <button className="btn-secondary inline-flex items-center gap-1.5 text-sm" onClick={() => onSiteTab("files")}><Icon name="folder" size={15} /> Open files</button>
        </div>
      </div>

      <div className="mb-6 flex gap-1 overflow-x-auto border-b border-white/[0.06]">
        {SITE_TABS.map(([key, label]) => (
          <button
            key={key}
            type="button"
            onClick={() => onSiteTab(key)}
            className={`whitespace-nowrap border-b-2 px-3.5 py-2.5 text-sm font-semibold transition-colors ${siteTab === key ? "border-brand-400 text-white" : "border-transparent text-slate-400 hover:text-white"}`}
          >
            {label}
          </button>
        ))}
      </div>

      <div className="animate-fade-up">{body}</div>
    </div>
  );
}

/* ----- per-site: install control shared by Overview + App tabs -------------- */

function SiteInstaller({ account, site, onSitesChanged }: { account: HostingAccountView; site: HostingWebsiteView; onSitesChanged: () => void }) {
  const [apps, setApps] = useState<{ slug: string; name: string; needsDb: boolean }[]>([]);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  useEffect(() => { listAppCatalog().then(setApps).catch(() => {}); }, []);

  async function install(value: string) {
    if (!value) return;
    setBusy(true); setErr("");
    const r = value === "wordpress" ? await installWordPress(account.id, targetOf(site)) : await installApp(account.id, value, targetOf(site));
    setBusy(false);
    if (r.error) setErr(r.error); else onSitesChanged();
  }

  const settling = site.status === "PENDING" || site.status === "DELETING";
  return (
    <div>
      <div className="flex flex-wrap items-center gap-2">
        <select
          className="input py-1.5 text-sm"
          defaultValue=""
          disabled={busy || settling}
          onChange={(e) => { const v = e.target.value; e.currentTarget.value = ""; install(v); }}
        >
          <option value="">{busy ? "Working…" : site.installedApp ? "Install another app…" : "Install an app…"}</option>
          <option value="wordpress">WordPress (auto)</option>
          {apps.map((ap) => (<option key={ap.slug} value={ap.slug}>{ap.name}</option>))}
        </select>
        {site.installedApp && <span className="text-xs text-slate-500">Currently: <span className="text-slate-300">{site.installedApp}</span></span>}
      </div>
      {err && <p className="mt-2 text-sm text-red-400">{err}</p>}
    </div>
  );
}

/* ----- per-site: thumbnail preview + upload/remove -------------------------- */

function SitePreviewCard({ account, site, onSitesChanged }: { account: HostingAccountView; site: HostingWebsiteView; onSitesChanged: () => void }) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);

  async function upload(file: File) {
    setBusy(true); setErr("");
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch(`/api/hosting/${account.id}/thumbnail?site=${encodeURIComponent(site.key)}`, { method: "POST", body: fd });
      const j = await res.json().catch(() => ({}));
      if (!res.ok) { setErr(j.error ?? "Upload failed."); return; }
      onSitesChanged();
    } catch {
      setErr("Upload failed.");
    } finally {
      setBusy(false);
    }
  }

  async function remove() {
    setBusy(true); setErr("");
    const r = await removeHostingThumbnail(account.id, site.key);
    setBusy(false);
    if (r.error) setErr(r.error); else onSitesChanged();
  }

  return (
    <div className="card p-0">
      <div className="relative aspect-[16/9] w-full overflow-hidden rounded-t-2xl border-b border-white/[0.06]">
        <Thumbnail accountId={account.id} site={site} />
      </div>
      <div className="flex flex-wrap items-center gap-2 p-3">
        <input
          ref={fileRef}
          type="file"
          accept="image/png,image/jpeg,image/gif,image/webp"
          className="hidden"
          onChange={(e) => { const f = e.target.files?.[0]; if (f) upload(f); e.currentTarget.value = ""; }}
        />
        <button className="btn-secondary inline-flex items-center gap-1.5 text-xs" disabled={busy} onClick={() => fileRef.current?.click()}>
          <Icon name="upload" size={14} /> {busy ? "Uploading…" : site.thumbnailAt ? "Replace thumbnail" : "Upload thumbnail"}
        </button>
        {site.thumbnailAt && (
          <button className="btn-ghost inline-flex items-center gap-1.5 text-xs text-slate-400 hover:text-white" disabled={busy} onClick={remove}>
            <Icon name="trash" size={14} /> Remove
          </button>
        )}
      </div>
      {err && <p className="px-3 pb-3 text-xs text-red-400">{err}</p>}
    </div>
  );
}

