      )}
      <div className="mt-4 flex flex-wrap gap-2">
        {site.canSetPrimary && <button className="btn-secondary inline-flex items-center gap-1.5 text-sm" disabled={busy} onClick={promote}><Icon name="star" size={15} /> Make main domain</button>}
