function SiteSettingsTab({
  account, site, onSection, onSitesChanged, onHub,
}: {
  account: HostingAccountView; site: HostingWebsiteView; onSection: (s: string) => void; onSitesChanged: () => void; onHub: () => void;
}) {
  const [busy, setBusy] = useState(false);
  async function remove() {
    if (!site.id) return;
    if (!confirm(`Delete ${site.hostname}? Its files will be removed.`)) return;
    setBusy(true);
    const r = site.kind === "subdomain" ? await deleteSubdomain(site.id) : await deleteAddonDomain(site.id);
    setBusy(false);
    if (r.error) { alert(r.error); return; }
    onSitesChanged();
    onHub();
  }
  return (
    <div className="space-y-6">
      <div className="card max-w-2xl">
        <h3 className="mb-1 font-semibold">Runtime</h3>
        <p className="text-sm text-slate-400">PHP <span className="font-mono text-slate-200">{site.phpVersion}</span> — the PHP runtime applies to every website on the plan. Change it in the plan <button type="button" className="text-brand-300 hover:underline" onClick={() => onSection("settings")}>Settings</button>.</p>
      </div>
      {site.kind === "primary" ? (
        <div className="card max-w-2xl">
          <h3 className="mb-1 font-semibold">Main website</h3>
          <p className="text-sm text-slate-400">This is the plan’s main website and can’t be deleted. Promote another site to main to change which one answers on the primary docroot.</p>
        </div>
      ) : (
        <div className="card max-w-2xl border-red-500/20">
          <h3 className="mb-1 font-semibold text-red-300">Delete this website</h3>
          <p className="mb-3 text-sm text-slate-400">Removes {site.hostname} and its files from the plan. This can’t be undone.</p>
          <button className="btn-danger inline-flex items-center gap-1.5 text-sm" disabled={busy} onClick={remove}><Icon name="trash" size={15} /> {busy ? "Deleting…" : `Delete ${site.hostname}`}</button>
        </div>
      )}
    </div>
  );
}

function ManagedAtPlan({ section, label, note, onSection }: { section: string; label: string; note: string; onSection: (s: string) => void }) {
  return (
    <div className="card max-w-2xl">
      <h3 className="mb-1 font-semibold">{label} — managed at plan level</h3>
      <p className="mb-4 text-sm text-slate-400">{note}</p>
      <button className="btn-primary text-sm" onClick={() => onSection(section)}>Open plan {label}</button>
    </div>
  );
}
